// Package numeric 实现本地数值作业的提交、调度、取消与结果归档。
//
// 作业对有符号 64 位整数序列计算总和 (sum) 与平方和 (sum of squares)，
// 本地一次只运行一个作业，其余可运行作业严格按提交先后依次执行；
// 等待依赖结果的作业不会挡住后面可运行的作业。
//
// 所有已确认的状态（提交、取消、成功/失败结果）都持久化到目录中，
// 重新打开目录后可以继续工作，幂等请求号继续有效。
package numeric

import (
	"errors"
	"time"
)

// Status 表示作业的状态。
type Status string

const (
	// StatusQueued 表示作业已接受并排队等待计算位置。
	StatusQueued Status = "queued"
	// StatusRunning 表示正在计算。
	StatusRunning Status = "running"
	// StatusSucceeded 表示计算成功且结果已归档。
	StatusSucceeded Status = "succeeded"
	// StatusFailed 表示作业失败（输入溢出、依赖未通过、重启中断等）。
	StatusFailed Status = "infailed"
	// StatusCanceled 表示作业被取消。
	StatusCanceled Status = "canceled"
)

// WaitReason 描述排队作业当前在等什么。
type WaitReason string

const (
	// WaitSlot 表示在等待本地唯一的计算位置。
	WaitSlot WaitReason = "waiting for computation slot"
	// WaitDependency 表示在等待依赖作业产出可使用的 resolved 状态。
	WaitDependency WaitReason = "waiting for dependency result"
)

// Job 是作业元数据的只读视图。
//
// 调用方修改返回的切片与时间均不影响内部状态与已保存记录。
type Job struct {
	ID           uint64
	Submitter    string
	RequestID    string
	Reused       bool
	ReusedSaidConflict bool
	ReusedSaidReuse    bool
	Seed         int64
	Values       []int64
	DependencyID uint64
	HasDependency bool

	// QueuedAt 为接受提交的时间，列举时按它排序。
	QueuedAt time.Time
	// StartedAt / FinishedAt 分别标记进入运行与终态的时间。
	StartedAt  time.Time
	FinishedAt time.Time

	// TerminalWait 仅用于内部：不再参与调度的排队作业（等待一个永远不会成功的依赖）。
	TerminalWait bool

	Status     Status
	WaitReason WaitReason
	FailureReason string

	// EffectiveInputs 是实际参与计算的输入摘要：原序列 + 依赖总和（若有且其结果已归档）。
	EffectiveInputs []int64
	// EffectiveCount 给出实际参与计算的整数个数。
	EffectiveCount int

	// 归档视图（仅成功时有效）。
	Archive *Archive
}

// Archive 是成功作业的完整归档记录。

