// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
// 排队作业原样保留在磁盘上，下次 [Open] 继续。
func (s *Store) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	s.mu.Unlock()

	if s.stopping.CompareAndSwap(false, true) {
		close(s.stopCh)
	}
	// 中止正在运行的作业。
	if j := s.runningJob(); j != nil {
		j.canceled.Store(true)
	}
	s.notify()
	s.wg.Wait()
	return nil
}

func (s *Store) runningJob() *storedJob {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.runningID == 0 {
		return nil
	}
	return s.byID[s.runningID]
}

