func TestDependencyWaitDoesNotBlockRunnableJobs(t *testing.T) {
	s, _ := openTestStore(t)
	started, release, _, _ := gateCompute(t, s)

	first := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}}) // id 1，先占住
	waitStarted(t, started, first.ID)

	waiting := mustSubmit(t, s, SubmitRequest{ // id 2，依赖 1
		Submitter: "a", Values: []int64{2},
		HasDependency: true, DependencyID: first.ID,
	})
	runnable := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{3}}) // id 3，无依赖

	// id 3 必须越过等待依赖的 id 2 先运行。
	waitStarted(t, started, runnable.ID)
	if j, _ := s.Get(waiting.ID); j.WaitReason != WaitDependency {
		t.Fatalf("waiting job reason=%q, want WaitDependency", j.WaitReason)
	}
	if j, _ := s.Get(runnable.ID); j.Status != StatusRunning {
		t.Fatalf("runnable job status=%s, want running", j.Status)
	}
	release(runnable.ID)
	waitStatus(t, s, runnable.ID, StatusSucceeded)

	// id 1 仍未完成，id 2 必须继续等待（且不挡任何人——此刻没有别的作业）。
	if j, _ := s.Get(waiting.ID); j.Status != StatusQueued || j.WaitReason != WaitDependency {
		t.Fatalf("waiting job status=%s reason=%q", j.Status, j.WaitReason)
	}
	release(first.ID)
	waitStatus(t, s, first.ID, StatusSucceeded)
	w := waitStatus(t, s, waiting.ID, StatusSucceeded)
	if w.Archive.Sum != 2+1 {
		t.Fatalf("dependent sum=%d, want 3", w.Archive.Sum)
	}
}

