input.old_string:
// gateCompute 安装可阻塞的计算钩子：started 收到进入计算的作业号，
// release(id) 放行；计算仍由真实 computeResult 完成，顺序记录到 order。
func gateCompute(t *testing.T, s *Store) (started chan uint64, release func(id uint64), order *[]uint64, mu *sync.Mutex) {
	t.Helper()
	started = make(chan uint64, 64)
	block := make(map[uint64]chan struct{})
	var bmu sync.Mutex
	var ord []uint64
	omu := &sync.Mutex{}
	s.compute = func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
		started <- id
		bmu.Lock()
		ch := block[id]
		bmu.Unlock()
		if ch != nil {
			<-ch
		}
		omu.Lock()
		ord = append(ord, id)
		omu.Unlock()
		return computeResult(inputs, seed, canceled)
	}
	release = func(id uint64) {
		bmu.Lock()
		defer bmu.Unlock()
		if ch, ok := block[id]; ok {
			close(ch)
			return
		}
		ch = make(chan struct{})
		close(ch)
		block[id] = ch
	}
	// 默认全部阻塞：预登记每个可能的 id 的 channel。
	preregister := func(ids ...uint64) {
		bmu.Lock()
		defer bmu.Unlock()
		for _, id := range ids {
			block[id] = make(chan struct{})
		}
	}
	_ = preregister
	return started, release, &ord, omu
}

