		ch, ok := gates[id]
		bmu.Unlock()
		if ok {
			close(ch)
		}
	}
	s.compute = func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
		started <- id
		bmu.Lock()
		ch := gates[id]
		bmu.Unlock()
		if ch != nil {
			<-ch
		}
		omu.Lock()
		ord = append(ord, id)
		omu.Unlock()
		return computeResult(inputs, seed, canceled)
	}
	return started, block, release, &ord, omu
}

