1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	type Store struct {
32		dir string
33	
34		mu     sync.Mutex
35		jobs   []*storedJob          // 严格按作业号（即提交先后）排列
36		byID   map[uint64]*storedJob
37		idem   map[string]uint64     // submitter\x00requestID -> 作业号
38		nextID uint64
39		closed bool
40	
41		now func() time.Time
42	
43		runningID uint64
44		waitCh    chan struct{}
45		stopCh    chan struct{}
46		stopping  atomic.Bool
47		wg        sync.WaitGroup
48	
49		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
50		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
51		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
52		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
53	}
54	
55	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
56	//
57	// 恢复语义：
58	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
59	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
60	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
61	//   - 成功状态始终与完整归档同时可见。
62	func Open(dir string, opts ...Option) (*Store, error) {
63		if err := os.MkdirAll(dir, 0o700); err != nil {
64			return nil, err
65		}
66		jobs, maxID, err := loadDir(dir)
67		if err != nil {
68			return nil, err
69		}
70		s := &Store{
71			dir:    dir,
72			jobs:   jobs,
73			byID:   make(map[uint64]*storedJob),
74			idem:   make(map[string]uint64),
75			nextID: maxID + 1,
76			now:    wallClock{}.Now,
77			waitCh: make(chan struct{}, 1),
78			stopCh: make(chan struct{}),
79		}
80		for _, opt := range opts {
81			opt(s)
82		}
83		for _, j := range jobs {
84			s.byID[j.id] = j
85			if j.requestID != "" {
86				s.idem[s.idemKey(j.submitter, j.requestID)] = j.id
87			}
88		}
89		// 重建失败/取消作业对排队下游的阻断。
90		s.cascadeLocked()
91		s.wg.Add(1)
92		go s.worker()
93		return s, nil
94	}
95	
96	func (s *Store) idemKey(submitter, requestID string) string {
97		return submitter + "\x00" + requestID
98	}
99	
100	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
101	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
102	func (s *Store) Close() error {
103		s.mu.Lock()
104		if s.closed {
105			s.mu.Unlock()
106			return nil
107		}
108		s.closed = true
109		var running *storedJob
110		if s.runningID != 0 {
111			running = s.byID[s.runningID]
112		}
113		s.mu.Unlock()
114	
115		if s.stopping.CompareAndSwap(false, true) {
116			close(s.stopCh)
117		}
118		// 中止正在运行的计算。
119		if running != nil {
120			running.canceled.Store(true)
121		}
122		s.notify()
123		s.wg.Wait()
124		return nil
125	}
126	
127	// Submit 接受一次作业提交。
128	//
129	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
130	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
131	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
132	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
133	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		if s.closed || s.stopping.Load() {
137			return nil, ErrStoreClosed
138		}
139		if len(req.Values) == 0 {
140			return nil, ErrEmptySequence
141		}
142		var dep *storedJob
143		if req.HasDependency {
144			dep = s.byID[req.DependencyID]
145			if dep == nil {
146				return nil, fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, req.DependencyID)
147			}
148		}
149		if req.RequestID != "" {
150			key := s.idemKey(req.Submitter, req.RequestID)
151			if origID, ok := s.idem[key]; ok {
152				orig := s.byID[origID]
153				if sameContent(orig, &req) {
154					return s.viewLocked(orig), nil
155				}
156				return s.viewLocked(orig),
157					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
158						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
159			}
160		}
161	
162		now := s.now().UTC()
163		j := &storedJob{
164			id:            s.nextID,
165			submitter:     req.Submitter,
166			requestID:     req.RequestID,
167			seed:          req.Seed,
168			values:        append([]int64(nil), req.Values...),
169			hasDependency: req.HasDependency,
170			dependencyID:  req.DependencyID,
171			queuedAt:      now,
172			status:        StatusQueued,
173		}
174		// 先持久化，接受之后该提交即不可丢失。
175		if err := s.persist(j); err != nil {
176			return nil, err
177		}
178		s.nextID++
179		s.jobs = append(s.jobs, j)
180		s.byID[j.id] = j
181		if req.RequestID != "" {
182			s.idem[s.idemKey(req.Submitter, req.RequestID)] = j.id
183		}
184		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
185		s.cascadeLocked()
186		s.notifyLocked()
187		return s.viewLocked(j), nil
188	}
189	
190	// sameContent 判断两次提交的内容是否一致；整数次序不同即视为不同内容。
191	func sameContent(j *storedJob, req *SubmitRequest) bool {
192		if j.seed != req.Seed || j.hasDependency != req.HasDependency {
193			return false
194		}
195		if j.hasDependency && j.dependencyID != req.DependencyID {
196			return false
197		}
198		if len(j.values) != len(req.Values) {
199			return false
200		}
201		for i := range j.values {
202			if j.values[i] != req.Values[i] {
203				return false
204			}
205		}
206		return true
207	}
208	
209	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
210	func (s *Store) Get(id uint64) (*Job, error) {
211		s.mu.Lock()
212		defer s.mu.Unlock()
213		j := s.byID[id]
214		if j == nil {
215			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
216		}
217		return s.viewLocked(j), nil
218	}
219	
220	// Cancel 请求取消作业。
221	//
222	// 排队或运行中的作业都可以取消；取消一旦返回成功，该作业及依赖它的作业
223	// 都不会再产生成功归档。重复取消已取消的作业仍返回成功；对已成功或已
224	// 失败的作业取消返回 [ErrNotCancellable]，原结果保持不变。
225	func (s *Store) Cancel(id uint64) (*Job, error) {
226		s.mu.Lock()
227		defer s.mu.Unlock()
228		if s.closed {
229			return nil, ErrStoreClosed
230		}
231		j := s.byID[id]
232		if j == nil {
233			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
234		}
235		switch j.status {
236		case StatusCanceled:
237			return s.viewLocked(j), nil
238		case StatusSucceeded, StatusFailed:
239			return s.viewLocked(j),
240				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
241		}
242	
243		// queued / running：立刻把终态落盘，使“已确认的取消”不会因崩溃丢失。
244		now := s.now().UTC()
245		j.status = StatusCanceled
246		j.failureReason = ""
247		j.blockerID = 0
248		if j.finishedAt.IsZero() {
249			j.finishedAt = now
250		}
251		j.effectiveValues = nil
252		j.archive = nil
253		j.canceled.Store(true)
254		if err := s.persist(j); err != nil {
255			return nil, err
256		}
257		// 依赖它的等待者一并失败，且继续向更下游传播。
258		s.cascadeLocked()
259		s.notifyLocked()
260		return s.viewLocked(j), nil
261	}
262	
263	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
264	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
265	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
266		s.mu.Lock()
267		defer s.mu.Unlock()
268		if !start.IsZero() && !end.IsZero() && start.After(end) {
269			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
270				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
271		}
272		out := make([]*Job, 0)
273		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
274			if j.submitter != submitter {
275				continue
276			}
277			if !start.IsZero() && j.queuedAt.Before(start) {
278				continue
279			}
280			if !end.IsZero() && j.queuedAt.After(end) {
281				continue
282			}
283			out = append(out, s.viewLocked(j))
284		}
285		return out, nil
286	}
287	
288	// cascadeLocked 把“依赖已失败/取消”的排队作业标记为失败并递归传播。
289	//
290	// 依赖在提交时必须已存在，因此依赖作业号必然更小，按作业号升序单趟
291	// 扫描即可让阻断沿链条传播到最下游。
292	func (s *Store) cascadeLocked() {
293		for _, j := range s.jobs {
294			if j.status != StatusQueued || !j.hasDependency {
295				continue
296			}
297			dep := s.byID[j.dependencyID]
298			if dep == nil {
299				continue
300			}
301			if dep.status != StatusFailed && dep.status != StatusCanceled {
302				continue
303			}
304			root := dep.blockerID
305			if root == 0 {
306				root = dep.id
307			}
308			s.markFailedLocked(j, blockedReason(dep, root), root)
309		}
310	}
311	
312	func blockedReason(dep *storedJob, root uint64) string {
313		state := "失败"
314		if dep.status == StatusCanceled {
315			state = "被取消"
316		}
317		reason := fmt.Sprintf("依赖的作业 %d 已%s，阻断本作业继续计算", dep.id, state)
318		if dep.status == StatusFailed && dep.failureReason != "" {
319			reason += "（其失败原因：" + dep.failureReason + "）"
320		}
321		if root != dep.id {
322			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
323		}
324		return reason
325	}
326	
327	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
328	// 等待依赖（依赖排队/运行中）的作业会被跳过，不挡住后面的作业。
329	func (s *Store) pickRunnableLocked() *storedJob {
330		for _, j := range s.jobs {
331			if j.status != StatusQueued {
332				continue
333			}
334			if !j.hasDependency {
335				return j
336			}
337			if dep := s.byID[j.dependencyID]; dep != nil && dep.status == StatusSucceeded {
338				return j
339			}
340		}
341		return nil
342	}
343	
344	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
345	func (s *Store) notifyLocked() {
346		select {
347		case s.waitCh <- struct{}{}:
348		default:
349		}
350	}
351	
352	// notify 在不持锁时唤醒 worker。
353	func (s *Store) notify() {
354		s.mu.Lock()
355		s.notifyLocked()
356		s.mu.Unlock()
357	}
358	
359	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
360	func (s *Store) persistRetry(j *storedJob, attempts int) error {
361		var err error
362		for i := 0; i < attempts; i++ {
363			if err = s.persist(j); err == nil {
364				return nil
365			}
366		}
367		return err
368	}
369	
370	// worker 是本地唯一的计算执行体。
371	func (s *Store) worker() {
372		defer s.wg.Done()
373		for {
374			s.mu.Lock()
375			if s.stopping.Load() {
376				s.mu.Unlock()
377				return
378			}
379			j := s.pickRunnableLocked()
380			if j == nil {
381				ch := s.waitCh
382				s.mu.Unlock()
383				select {
384				case <-ch:
385				case <-s.stopCh:
386				}
387				continue
388			}
389	
390			// 进入运行并原子持久化该状态。
391			j.status = StatusRunning
392			j.startedAt = s.now().UTC()
393			inputs := append([]int64(nil), j.values...)
394			if j.hasDependency {
395				if dep := s.byID[j.dependencyID]; dep != nil && dep.archive != nil {
396					inputs = append(inputs, dep.archive.Sum)
397				}
398			}
399			seed := j.seed
400			s.runningID = j.id
401			if err := s.persistRetry(j, 3); err != nil {
402				// 连运行状态都无法落盘：保守地失败，不进行计算。
403				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
404				s.runningID = 0
405				s.cascadeLocked()
406				s.notifyLocked()
407				s.mu.Unlock()
408				continue
409			}
410			s.mu.Unlock()
411	
412			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
413			doCompute := s.compute
414			if doCompute == nil {
415				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
416					return computeResult(in, sd, c)
417				}
418			}
419			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
420	
421			s.mu.Lock()
422			s.runningID = 0
423			switch {
424			case j.status == StatusCanceled:
425				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
426				j.archive = nil
427				j.effectiveValues = nil
428				_ = s.persistRetry(j, 3)
429				s.cascadeLocked()
430			case s.stopping.Load():
431				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
432				s.cascadeLocked()
433			case !ok:
434				s.markFailedLocked(j, reason, 0)
435				s.cascadeLocked()
436			default:
437				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
438				completed := s.now().UTC()
439				a := newArchive(j, inputs, sum, sumSq, completed)
440				j.effectiveValues = append([]int64(nil), inputs...)
441				j.status = StatusSucceeded
442				j.finishedAt = completed
443				j.failureReason = ""
444				j.blockerID = 0
445				j.archive = a
446				if err := s.persistRetry(j, 3); err != nil {
447					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
448					j.archive = nil
449					j.effectiveValues = nil
450					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
451				}
452			}
453			s.notifyLocked()
454			s.mu.Unlock()
455		}
456	}
457	
458	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
459	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
460		j.status = StatusFailed
461		j.failureReason = reason
462		j.blockerID = blocker
463		if j.finishedAt.IsZero() {
464			j.finishedAt = s.now().UTC()
465		}
466		j.archive = nil
467		j.effectiveValues = nil
468		_ = s.persistRetry(j, 3)
469	}
470	
471	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
472	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
473		inDigest := inputsDigestHex(effective, j.seed)
474		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
475		log := buildLog(effective, j.seed, sum, sumSquares)
476		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
477		return &Archive{
478			JobID:           j.id,
479			Submitter:       j.submitter,
480			RequestID:       j.requestID,
481			Seed:            j.seed,
482			Values:          append([]int64(nil), j.values...),
483			HasDependency:   j.hasDependency,
484			DependencyID:    j.dependencyID,
485			EffectiveValues: append([]int64(nil), effective...),
486			InputsDigest:    inDigest,
487			Sum:             sum,
488			SumOfSquares:    sumSquares,
489			ResultDigest:    resDigest,
490			Log:             log,
491			Checksum:        checksum,
492			CompletedAt:     completedAt,
493		}
494	}
495	
496	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
497	func (s *Store) viewLocked(j *storedJob) *Job {
498		v := &Job{
499			ID:              j.id,
500			Submitter:       j.submitter,
501			RequestID:       j.requestID,
502			Seed:            j.seed,
503			Values:          append([]int64(nil), j.values...),
504			HasDependency:   j.hasDependency,
505			DependencyID:    j.dependencyID,
506			QueuedAt:        j.queuedAt,
507			StartedAt:       j.startedAt,
508			FinishedAt:      j.finishedAt,
509			Status:          j.status,
510			FailureReason:   j.failureReason,
511			BlockerID:       j.blockerID,
512			EffectiveValues: append([]int64(nil), j.effectiveValues...),
513		}
514		if j.status == StatusQueued {
515			v.WaitReason = WaitSlot
516			if j.hasDependency {
517				if dep := s.byID[j.dependencyID]; dep == nil || dep.status != StatusSucceeded {
518					v.WaitReason = WaitDependency
519				}
520			}
521		}
522		if j.archive != nil {
523			a := *j.archive
524			a.Values = append([]int64(nil), j.archive.Values...)
525			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
526			v.Archive = &a
527		}
528		return v
529	}
530	
531	// Dir 返回归档目录路径。
532	func (s *Store) Dir() string { return s.dir }
533

